# Lore test-command interface (lore_list_tests / lore_run_test).
# Written for this repo's Jest suite rather than adapted from the Vitest
# equivalent for a Vitest suite: the report shapes happen to match, but the
# invocations do not.
- id: hal-engine-jest
  name: HAL Engine Jest suite
  cwd: .
  description: >-
    The ts-jest unit suite over src/ and scripts/ (jest.config.js roots), run
    on every pull request in .github/workflows/ci.yml as the "Test" step.
    Selectors are "<repo-relative-file>::<full test name>" as emitted by the
    list command. Jest has no dry-run, so the list command executes the suite
    once with --json and derives every name from the report; it deliberately
    tolerates a red suite, since listing must not depend on the tests passing.
    The run command selects one test with --runTestsByPath plus an anchored,
    regex-escaped -t, and treats a selector that matches nothing as a failure
    rather than a green run of an empty suite. Neither command builds first:
    no test here reads dist/.
  list: node scripts/lore-list-tests.mjs
  run: node scripts/lore-run-test.mjs "{selector}"
  coverage_format: lcov
import {jest} from '@jest/globals';
import Ajv from 'ajv';
import {ToolRegistry, type ToolExecutor} from './registry.js';

const callCount = (executor: {mock: {calls: unknown[]}}): number => {
  const calls = executor.mock.calls;
  return calls.length;
};

const firstCallInput = (executor: {mock: {calls: unknown[][]}}): unknown => {
  const calls = executor.mock.calls;
  const firstCall = calls[0];
  return firstCall?.[0];
};

const registerWeatherTool = (registry: ToolRegistry, executor: ToolExecutor): void => {
  registry.register(
    {
      name: 'get_weather',
      description: 'Get weather for a location',
      inputSchema: {
        type: 'object',
        properties: {location: {type: 'string'}},
        required: ['location'],
      },
    },
    executor
  );
};

describe('ToolRegistry', () => {
  it('returns a required-property rejection without invoking the executor', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn(async () => 'sunny');
    registerWeatherTool(registry, executor);

    const response = await registry.execute('get_weather', {});

    expect({
      resultNamesRequiredLocation: /location.*required|required.*location/i.test(response.result),
      executorCalls: callCount(executor),
    }).toEqual({resultNamesRequiredLocation: true, executorCalls: 0});
  });

  it('includes the nested property path for a missing required value', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn(async () => 'ok');
    registry.register(
      {
        name: 'nested_tool',
        description: 'Read a nested value',
        inputSchema: {
          type: 'object',
          properties: {
            profile: {
              type: 'object',
              properties: {location: {type: 'string'}},
              required: ['location'],
            },
          },
        },
      },
      executor
    );

    const response = await registry.execute('nested_tool', {profile: {}});

    expect({
      resultNamesRequiredNestedLocation: /profile\.location.*required|required.*profile\.location/i.test(
        response.result
      ),
      executorCalls: callCount(executor),
    }).toEqual({resultNamesRequiredNestedLocation: true, executorCalls: 0});
  });

  it('compiles a function-valued schema once when the same schema object is reused', async () => {
    const inputSchema = {type: 'object', properties: {}};
    const registry = new ToolRegistry();
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    registry.register(
      () => ({name: 'dynamic_tool', description: 'Dynamic schema', inputSchema}),
      async () => 'ok'
    );

    await registry.execute('dynamic_tool', {});
    await registry.execute('dynamic_tool', {});

    expect(compile).toHaveBeenCalledTimes(1);
    compile.mockRestore();
  });

  it('passes valid input with extra properties through unchanged exactly once', async () => {
    const registry = new ToolRegistry();
    const input = {location: 'Paris', unit: 'celsius'};
    const executor = jest.fn(async (_input: Record<string, unknown>) => 'sunny');
    registerWeatherTool(registry, executor);

    await registry.execute('get_weather', input);

    expect({calls: callCount(executor), input: firstCallInput(executor)}).toEqual({
      calls: 1,
      input,
    });
  });

  it('rejects a wrong type with the field path and expected type without exposing the value', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn(async () => 'sunny');
    registerWeatherTool(registry, executor);

    const response = await registry.execute('get_weather', {location: 8675309});

    expect({
      result: response.result,
      executorCalls: callCount(executor),
    }).toEqual({result: 'Input validation failed at location: expected string', executorCalls: 0});
  });

  it('reports root property paths without a leading dot', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn(async () => 'ok');
    registerWeatherTool(registry, executor);

    const response = await registry.execute('get_weather', {location: 8675309});

    expect({result: response.result, calls: callCount(executor)}).toEqual({
      result: 'Input validation failed at location: expected string',
      calls: 0,
    });
  });
});

describe('ToolRegistry unknown tools', () => {
  it('throws the unchanged unknown-tool error for an unregistered name', async () => {
    const registry = new ToolRegistry();

    await expect(registry.execute('missing_tool', {})).rejects.toThrow('Unknown tool: missing_tool');
  });
});
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by: returns a required-property rejection without invoking the executor](../../src/orchestration/tools/registry.test.ts#L32), [validated by: includes the nested property path for a missing required value](../../src/orchestration/tools/registry.test.ts#L45), [acceptance: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L16)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by: rejects a wrong type with the field path and expected type without exposing the value](../../src/orchestration/tools/registry.test.ts#L106), [acceptance: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults ([validated by: passes valid input with extra properties through unchanged exactly once](../../src/orchestration/tools/registry.test.ts#L92)).
- For a root-level invalid property, the rejection names the property path without adding a leading dot ([validated by: reports root property paths without a leading dot](../../src/orchestration/tools/registry.test.ts#L119)).
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake ([validated by: throws the unchanged unknown-tool error for an unregistered name](../../src/orchestration/tools/registry.test.ts#L135)).

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L94)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema`.
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules.
- Reusing the same schema object from a function-valued `ToolDefinitionSource` compiles it only once ([validated by: compiles a function-valued schema once when the same schema object is reused](../../src/orchestration/tools/registry.test.ts#L76)).

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L112)).

